"""EMS Factory"""
from __future__ import absolute_import, division, print_function,\
    unicode_literals
from builtins import object
from ta_emss import ta_emss
from future import standard_library
standard_library.install_aliases()


class EmssimFactory(object):
    """EMS factory"""
    INSTANCE = None

    def __init__(self):
        self.ta_emss = ta_emss()

    @classmethod
    def get_instance(cls):
        """Get EMS instance"""
        if not cls.INSTANCE:
            cls.INSTANCE = EmssimFactory()
        return cls.INSTANCE
